public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be greater than 0");
    }
    if (N == 1) {
        return 0; // No time needed for a single person
    }
    // For even N, it takes N/2 minutes, for odd N, it takes (N-1) minutes
    return N % 2 == 0 ? N / 2 : N - 1;
}

