public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    boolean forward = true;
    int remaining = s.length();

    while (remaining > 0) {
        if (forward) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                    remaining--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
