public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 1) {
        return false;
    }

    int totalPossibleCodes = 1 << k; // 2^k
    boolean[] seen = new boolean[totalPossibleCodes];

    for (int i = 0; i <= s.length() - k; i++) {
        int value = 0;
        for (int j = i; j < i + k; j++) {
            value = (value << 1) + (s.charAt(j) - '0');
        }
        seen[value] = true;
    }

    for (boolean code : seen) {
        if (!code) {
            return false;
        }
    }

    return true;
}

