public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    for (int i = low; i <= Math.min(high, 9); i++) {
        result.add(i);
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int lastDigit = num % 10;
        int next1 = num * 10 + lastDigit - 1;
        int next2 = num * 10 + lastDigit + 1;

        if (lastDigit > 0 && next1 <= high) {
            queue.offer(next1);
        }
        if (lastDigit < 9 && next2 <= high) {
            queue.offer(next2);
        }
    }

    Collections.sort(result);
    return result;
}

